"""Accessibility-first progressive enhancement for first-party published forms.

No inline untrusted JavaScript or network dependency. Browsers without scripting
see all steps and fields; server-side conditions are always authoritative.
"""
SITE_FORM_CLIENT_JS = "(function () {\n  'use strict';\n  const form = document.querySelector('form[data-site-form]');\n  if (!form) return;\n  const steps = Array.from(form.querySelectorAll('[data-site-step]'));\n  if (!steps.length) return;\n  const conditionalGroups = Array.from(form.querySelectorAll('[data-condition-key]'));\n  const previous = form.querySelector('[data-site-back]');\n  const next = form.querySelector('[data-site-next]');\n  const submit = form.querySelector('[data-site-submit]');\n  const progress = form.querySelector('[data-site-progress]');\n  let current = 0;\n  const controls = (node) => Array.from(node.querySelectorAll('input:not([type=\"hidden\"]),select,textarea'));\n  const valueOf = (key) => {\n    const matches = Array.from(form.elements).filter((element) => element.name === key);\n    if (!matches.length) return '';\n    const first = matches[0];\n    if (first.type === 'checkbox') return first.checked ? 'true' : 'false';\n    if (first.type === 'radio') {\n      const checked = matches.find((item) => item.checked);\n      return checked ? checked.value : '';\n    }\n    return first.value;\n  };\n  const eligible = (group) => {\n    const conditionKey = group.dataset.conditionKey;\n    if (!conditionKey) return true;\n    return valueOf(conditionKey) === group.dataset.conditionEquals;\n  };\n  const apply = (allSteps) => {\n    for (const group of conditionalGroups) {\n      const visible = eligible(group);\n      group.hidden = !visible;\n      if (!visible) {\n        for (const input of controls(group)) {\n          if (input.type === 'checkbox' || input.type === 'radio') input.checked = false;\n          else input.value = '';\n        }\n      }\n    }\n    steps.forEach((step, stepIndex) => {\n      const active = allSteps || current === stepIndex;\n      step.hidden = !active;\n      for (const input of controls(step)) {\n        const group = input.closest('[data-condition-key]');\n        const allowed = active && (!group || eligible(group));\n        input.disabled = !allowed;\n        input.required = allowed && input.dataset.siteRequired === 'true';\n      }\n    });\n    if (previous) previous.hidden = allSteps || current === 0;\n    if (next) next.hidden = allSteps || current === steps.length - 1;\n    if (submit) submit.hidden = !allSteps && current !== steps.length - 1;\n    if (progress) progress.textContent = 'Step ' + (current + 1) + ' of ' + steps.length;\n  };\n  const invalidControl = (step) =>\n    controls(step).find((input) => !input.disabled && !input.checkValidity());\n  if (previous) previous.addEventListener('click', () => {\n    current = Math.max(0, current - 1);\n    apply(false);\n  });\n  if (next) next.addEventListener('click', () => {\n    const invalid = invalidControl(steps[current]);\n    if (invalid) { invalid.reportValidity(); return; }\n    current = Math.min(steps.length - 1, current + 1);\n    apply(false);\n  });\n  form.addEventListener('change', () => apply(false));\n  form.addEventListener('input', (event) => {\n    if (event.target && event.target.matches('select,input[type=\"radio\"],input[type=\"checkbox\"]')) {\n      apply(false);\n    }\n  });\n  form.addEventListener('submit', (event) => {\n    event.preventDefault();\n    apply(true);\n    const firstBadStep = steps.findIndex((step) => Boolean(invalidControl(step)));\n    if (firstBadStep >= 0) {\n      current = firstBadStep;\n      apply(false);\n      const invalid = invalidControl(steps[current]);\n      if (invalid) invalid.reportValidity();\n      return;\n    }\n    // Native posting retains idempotency hidden inputs and works without JS as well.\n    HTMLFormElement.prototype.submit.call(form);\n  });\n  if (previous) previous.hidden = false;\n  if (next) next.hidden = false;\n  apply(false);\n}());"
